 function activate(e){const b=e.target.closest?.('[data-food]');if(!b||!root.contains(b)||b.disabled||pointerCancelled||doc.hidden||!isAllowed())return;const action=b.dataset.food,s=controller.snapshot();if(action==='open')controller.open(s.seated?'dine':lastContext??'pouch');else if(action==='expand')compact=false;else if(action==='close')controller.close();else if(action==='cancel')controller.cancel();else if(action==='collect')controller.collect();else if(action==='retry')controller.retry();else if(action==='choose'){if(s.mode==='pack')controller.pack(select.value);else if(s.mode==='order')controller.order(select.value);else controller.eat(select.value);}else if(action==='invite')getTea()?.invite(friend.value);else if(action==='share')getTea()?.share(select.value);else if(action==='farewell')getTea()?.cancel('leave');render();}
